import styles from './Navbar.module.scss';
import React, { useEffect, useState } from 'react';
import $ from 'jquery';

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const sectionHeight = document.querySelector(`section`)?.offsetHeight || 0;
      setScrolled(window.scrollY > sectionHeight - 55);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [styles.section_1]);

  const [isClicked, setIsClicked] = useState(false);

  function showCircles() {

  }

  $("#circles-btn").on('click', () => {
    setIsClicked(!isClicked);
  });

  return (
    <nav className={scrolled ? styles.navbarScrolled : styles.navbar}>
      <div className={styles.logo}>
        <p>φιλία</p>
      </div>
      <ul>
        <li><a href="/about">Начало</a></li>
        <li><a href="/contact" id='circles-btn'>Кръгове</a></li>
        <li><a href="/login" className={styles.login_button}>Вход</a></li>
      </ul>
    </nav>
  );
}

export default Navbar;
